    mid = n // 2
    color = grid[mid][mid]
    if color == 7:
        color = grid[mid][mid + 1]
    out = [[7] * n for _ in range(n)]
    start = mid if n % 2 else mid - 1
    stop = mid if n % 2 else mid + 1
    if any(grid[r][c] == color for r in range(n) for c in range(stop, n)):
        for k, r in enumerate(range(start, -1, -1)):
            out[r][stop + k] = color
    else:
        for k, r in enumerate(range(start, n)):
            out[r][stop + k] = color
    return out
